/* The application shell: session, routing, the draft editor and view dispatch.
 *
 * The Leaflet container is created once and kept alive across re-renders --
 * everything around it is rebuilt from state, but the map itself is not.
 *
 * Anonymous visitors get the public catalog and nothing else: startup asks
 * only for /api/config, /api/session and the public catalog. The team's
 * inventory, bases and saved maps load only after an individual sign-in, and
 * are cancelled and cleared on logout or session expiry.
 *
 * The header, the map workspace, the catalog/inventory views, the legacy map
 * view and the legacy actions live in ./shell/; their shared state is
 * shell/context.js.
 */

import { abortPrivate, api, configureApi } from "../lib/api.js";
import { clear, el } from "../lib/dom.js";
import {
  defaultRoute, isPrivateRoute, navigate, parseRoute, routeHash, sameRoute,
} from "../lib/router.js";
import { clearPrivateState, getState, setState, subscribe } from "../lib/store.js";
import { loadCarpetas } from "./folders/folderActions.js";
import {
  cancelarCargas, cargar, cargarDetalle, pedirCarga, reemplazarRegistro,
} from "./inventory/datasets.js";
import { createTerrainEditor } from "./inventory/TerrainEditor.js";
import { openTerrainHistory } from "./inventory/TerrainHistory.js";
import { createSession } from "./session/session.js";
import { shell } from "./shell/context.js";
import { renderDatos } from "./shell/datosView.js";
import { renderHeader as dibujarCabecera } from "./shell/header.js";
import { renderBases, renderMapas } from "./shell/legacyActions.js";
import { renderMapa } from "./shell/mapaView.js";
import { confirmDialog } from "./ui/dialog.js";
import { clearToasts, toast, toastError } from "./ui/toast.js";

const REVALIDAR_MS = 10_000;   // focus/visibility revalidation, at most this often

let configReadOnly = false;
let session = null;
let editor = null;          // the open TerrainEditor, kept alive across renders
let editorEstado = null;    // { id, error } while an editor loads or failed to
let legacyCargado = false;  // bases/maps/folders loaded for this session
let ultimaRevalidacion = 0;

export async function mount(root) {
  try {
    const config = await api.config();
    configReadOnly = config.readOnly === true;
    shell.cloud = config.cloud === true;
    configureApi(config);
  } catch (error) {
    root.textContent = `No se pudo cargar la aplicación: ${error.message}`;
    return;
  }
  const header = el("header", { class: "app-header" });
  const main = el("main", { class: "app-main", id: "vista" });
  root.append(header, main);

  subscribe(() => {
    renderHeader(header);
    renderView(main);
  });

  // Escape closes the detail panel. Native <dialog> handles its own Escape and
  // stops the event, so this only ever fires when no dialog is open.
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    const { ruta, seleccionado } = getState();
    if ((ruta.nombre === "catalogo" || ruta.nombre === "inventario") && ruta.id) {
      navigate({ nombre: ruta.nombre }, { replace: true });
    } else if (ruta.nombre === "mapa" && seleccionado != null) {
      setState({ seleccionado: null });
    }
  });

  session = createSession({
    onSignedIn: alEntrar,
    onSignedOut: limpiarPrivado,
    hasUnsavedWork: () => Boolean(editor?.dirty),
  });

  window.addEventListener("hashchange", aplicarRuta);
  window.addEventListener("beforeunload", (event) => {
    if (editor?.dirty) { event.preventDefault(); event.returnValue = ""; }
  });
  // An open public page catches up when it is looked at again; nothing polls.
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") revalidar();
  });
  window.addEventListener("focus", revalidar);
  window.addEventListener("pageshow", (event) => { if (event.persisted) revalidar({ forzar: true }); });

  renderHeader(header);
  renderView(main);
  await session.refr

/* The list of imported workbooks, organized in folders. */

import { el } from "../../lib/dom.js";
import { TODAS, folderNameOf } from "../../lib/carpetas.js";
import { fmtCount, fmtDate, plural } from "../../lib/format.js";
import { FolderLabel, FolderedGallery } from "../folders/FolderNav.js";

export function BaseGallery({
  bases, carpetas = [], seleccion = TODAS, carpetasError = null,
  onOpen, onAppend, onRename, onDelete, onImport, onMove, onFormats,
  onSelectFolder, onCreateFolder, onRenameFolder, onDeleteFolder, onRetryFolders,
  readOnly = false,
}) {
  return el("div", { class: "screen" },
    el("header", { class: "screen-header" },
      el("div", {},
        el("span", { class: "eyebrow" }, "Bases"),
        el("h1", {}, "Bases de terrenos"),
        el("p", { class: "secondary" },
          readOnly ? "Abre una base para explorar sus terrenos en el mapa." :
          "Cada base es un archivo de Excel o CSV importado. Ábrela para verla en el mapa " +
          "o agrégale terrenos de otro archivo."),
      ),
      !readOnly && el("div", { class: "screen-actions" },
        el("button", { type: "button", class: "btn btn-quiet", onclick: onFormats },
          "Formatos de importación"),
        el("button", { type: "button", class: "btn btn-quiet", onclick: onCreateFolder },
          "Nueva carpeta"),
        el("button", { type: "button", class: "btn btn-principal", onclick: onImport },
          "Importar archivo"),
      ),
    ),

    FolderedGallery({
      tipo: "bases", items: bases, carpetas, seleccion, error: carpetasError, readOnly,
      onSelect: onSelectFolder, onRenameFolder, onDeleteFolder, onRetry: onRetryFolders,
      emptyAll: readOnly ? el("p", {}, "Todavía no hay bases publicadas.") : Empty(onImport),
      renderItems: (visibles) => el("ul", { class: "card-grid" },
          visibles.map((base) =>
            el("li", { class: "card" },
              el("button", {
                type: "button", class: "card-main", onclick: () => onOpen(base),
              },
                el("h2", { class: "card-title truncate", title: base.nombre }, base.nombre),
                el("p", { class: "card-figures figure" },
                  el("strong", {}, fmtCount(base.conteo)),
                  " terrenos · ",
                  el("span", { class: base.ubicados ? "" : "muted" }, fmtCount(base.ubicados)),
                  " en el mapa",
                ),
                base.sin_ubicacion > 0 && el("p", { class: "card-warn" },
                  `${plural(base.sin_ubicacion, "terreno")} fuera del mapa`,
                  base.ubicacion_invalida > 0
                    ? ` · ${base.ubicacion_invalida} con coordenadas imposibles`
                    : "",
                ),
                el("p", { class: "card-meta muted" },
                  `Importada el ${fmtDate(base.importado_en)}`),
                seleccion === TODAS && FolderLabel(folderNameOf(base, carpetas)),
              ),
              !readOnly && el("div", { class: "card-actions" },
                el("button", { type: "button", class: "link-btn", onclick: () => onAppend(base) },
                  "Agregar terrenos"),
                el("button", { type: "button", class: "link-btn", onclick: () => onMove(base) },
                  "Mover a carpeta…"),
                el("button", { type: "button", class: "link-btn", onclick: () => onRename(base) },
                  "Renombrar"),
                el("button", {
                  type: "button", class: "link-btn link-peligro", onclick: () => onDelete(base),
                }, "Eliminar"),
              ),
            )
          )
        ),
    }),
  );
}

function Empty(onImport) {
  return el("div", { class: "empty-state" },
    el("h2", {}, "Todavía no hay ninguna base"),
    el("p", { class: "secondary" },
      "Archivos admitidos: Excel (.xlsx, .xlsm) y CSV (.csv). En Excel se lee la " +
      "hoja «Registro Análisis»; en un CSV, la primera fila debe contener los "

/* Entry points for importing: pick a file, then hand it to the assistant.
 *
 * Both "Importar archivo" and "Agregar terrenos" go through the same
 * assistant (components/import/ImportAssistant.js): upload, automatic
 * analysis, only the questions that are needed, review with a map, import.
 */

import { el } from "../../lib/dom.js";
import { runAssistant } from "../import/ImportAssistant.js";

export function pickWorkbook() {
  return new Promise((resolve) => {
    const input = el("input", {
      type: "file",
      accept: ".xlsx,.xlsm,.csv",
      style: { display: "none" },
      onchange: () => { resolve(input.files?.[0] ?? null); input.remove(); },
    });
    document.body.append(input);
    input.click();
  });
}

/**
 * Import a new base. Resolves with the created base, or null if cancelled.
 * `carpetas` are the base folders it can go into; `carpetaInicial` is the one
 * preselected (the folder open in the gallery, or null for "Sin carpeta").
 */
export async function importWorkbook({ onDone, carpetas = [], carpetaInicial = null }) {
  const file = await pickWorkbook();
  return file ? runAssistant(file, { modo: "nueva", carpetas, carpetaInicial, onDone }) : null;
}

/** Append a file to an existing base, resolving conflicts row by row. */
export async function appendWorkbook(base, { onDone }) {
  const file = await pickWorkbook();
  return file ? runAssistant(file, { modo: "agregar", base, onDone }) : null;
}

/* Folder dialogs: name a folder, move an item, confirm a folder's removal, and
 * the destination field shared by every dialog that creates something.
 *
 * All are native <dialog>s (focus trap, Escape to cancel) with labelled fields
 * inside a <form>, so Enter submits. Typing never touches global state, so the
 * gallery re-rendering behind a dialog cannot steal its focus.
 */

import { el } from "../../lib/dom.js";
import { TEXTOS } from "../../lib/carpetas.js";
import { confirmDialog, openDialog } from "../ui/dialog.js";
import { toastError } from "../ui/toast.js";

const MAX_NOMBRE = 100;

/* A dialog whose body is a form: the primary action submits it. */
function formDialog({ titulo, descripcion, campos, etiqueta, onSubmit }) {
  // The footer buttons live outside the form, so a visually hidden submit
  // button gives Enter something to press in every field, radios included.
  const form = el("form", { class: "folder-form", novalidate: true }, campos,
    el("button", {
      type: "submit", class: "visually-hidden", tabindex: "-1", "aria-hidden": "true",
    }, etiqueta));
  let enviando = false;
  const { dialog, close } = openDialog({
    titulo, descripcion, contenido: form, ancho: "28rem",
    acciones: [
      { etiqueta: "Cancelar", onClick: (cerrar) => cerrar() },
      { etiqueta, variante: "principal", onClick: () => form.requestSubmit() },
    ],
  });
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (enviando) return;
    enviando = true;
    try { await onSubmit(close); } finally { enviando = false; }
  });
  return { dialog, close, form };
}

/** Ask for a folder name; `onSave(nombre)` may throw to keep the dialog open. */
export function promptFolderName({
  titulo, nombre = "", confirmar = "Guardar", etiqueta = "Nombre de la carpeta", onSave,
}) {
  const input = el("input", {
    class: "input", id: "carpeta-nombre", value: nombre, maxlength: String(MAX_NOMBRE),
    autocomplete: "off", required: true,
  });
  const { dialog } = formDialog({
    titulo,
    campos: el("div", { class: "rail-field" },
      el("label", { class: "field-label", for: "carpeta-nombre" }, etiqueta),
      input,
    ),
    etiqueta: confirmar,
    onSubmit: async (close) => {
      const limpio = input.value.replace(/\s+/g, " ").trim();
      if (!limpio) {
        toastError("El nombre no puede estar vacío.");
        input.focus();
        return;
      }
      try {
        await onSave(limpio);
        close();
      } catch (error) {
        toastError(error.message);
        input.focus();
        input.select();
      }
    },
  });
  input.select();
  return dialog;
}

/**
