/* Folder navigation for one dashboard, and the frame a gallery sits in.
 *
 * Wide screens get a list beside the cards; narrow ones a labelled select
 * above them. Both are rendered and CSS shows one, so the choice follows the
 * viewport without any script. Counts are of saved items (a comparison map is
 * one map), derived from the complete lists.
 */

import { el } from "../../lib/dom.js";
import { fmtCount, plural } from "../../lib/format.js";
import {
  SIN_CARPETA, TEXTOS, TODAS, filterByFolder, folderCounts, isFolderId, selectionLabel,
} from "../../lib/carpetas.js";

/**
 * The navigation, the heading of the open folder and the cards it holds.
 * `renderItems(visibles)` draws the cards; `emptyAll` is shown when there is
 * nothing at all and no folders either (the dashboard's original empty state).
 */
export function FolderedGallery({
  tipo, items, carpetas, seleccion, error, readOnly,
  onSelect, onRenameFolder, onDeleteFolder, onRetry,
  renderItems, emptyAll,
}) {
  if (!items.length && !carpetas.length && !error) return emptyAll;

  const visibles = filterByFolder(items, seleccion);
  const counts = folderCounts(items, carpetas);
  const textos = TEXTOS[tipo];

  return el("div", { class: "folder-layout" },
    FolderNav({ tipo, carpetas, counts, seleccion, error, onSelect, onRetry }),
    el("section", { class: "folder-content", "aria-labelledby": `folder-heading-${tipo}` },
      el("div", { class: "folder-heading" },
        el("div", {},
          el("h2", { id: `folder-heading-${tipo}`, class: "folder-title", tabindex: "-1" },
            selectionLabel(tipo, seleccion, carpetas)),
          el("p", { class: "muted figure" },
            plural(visibles.length, textos.singular, textos.plural)),
        ),
        !readOnly && isFolderId(seleccion) && el("div", { class: "folder-actions" },
          el("button", {
            type: "button", class: "link-btn",
            onclick: () => onRenameFolder(carpetas.find((c) => c.id === seleccion)),
          }, "Renombrar"),
          el("button", {
            type: "button", class: "link-btn link-peligro",
            onclick: () => onDeleteFolder(carpetas.find((c) => c.id === seleccion)),
          }, "Eliminar carpeta"),
        ),
      ),
      visibles.length
        ? renderItems(visibles)
        : el("p", { class: "folder-empty secondary" }, emptyText(tipo, seleccion, readOnly)),
    ),
  );
}

const VACIO = {
  bases: {
    [TODAS]: "Todavía no hay bases.",
    [SIN_CARPETA]: "Todas las bases están en alguna carpeta.",
    carpeta: "Esta carpeta está vacía. Usa «Mover a carpeta…» en una base para traerla aquí.",
  },
  mapas: {
    [TODAS]: "Todavía no hay mapas guardados.",
    [SIN_CARPETA]: "Todos los mapas están en alguna carpeta.",
    carpeta: "Esta carpeta está vacía. Usa «Mover a carpeta…» en un mapa para traerlo aquí.",
  },
};

function emptyText(tipo, seleccion, readOnly) {
  if (!isFolderId(seleccion)) return VACIO[tipo][seleccion];
  return readOnly ? "Esta carpeta está vacía." : VACIO[tipo].carpeta;
}

function FolderNav({ tipo, carpetas, counts, seleccion, error, onSelect, onRetry }) {
  const entradas = [
    { valor: TODAS, nombre: TEXTOS[tipo].todas, conteo: counts.todas },
    { valor: SIN_CARPETA, nombre: "Sin carpeta", conteo: counts.sinCarpeta },
    ...carpetas.map((c) => ({ valor: c.id, nombre: c.nombre, conteo: counts.porCarpeta.get(c.id) ?? 0 })),
  ];
  const selectId = `carpeta-select-${tipo}`;

  return el("nav", { class: "folder-nav", "aria-label": `Carpetas de ${TEXTOS[tipo].plural}` },
    el("ul", { class: "folder-nav-list" },
      entradas.map((entrada, index) =>
        el("li", { class: index === 2 ? "folder-nav-first" : null },
          el("button", {
            type: "button",
            class: ["folder-nav-item", entrada.valor === seleccion && "is-active"],
            "aria-current": entrada.valor === seleccion ? "true" : null,
            onclick: () => onSelect(entrada.valor),

/* What the folder controls do: load, create, rename, delete and move.
 *
 * Every change goes to the server first and the screen follows its answer; a
 * failed request leaves the previous placement visible and says why. Moving an
 * item patches that one object by id in the full list (and in the open map or
 * base, if it is that one), so an open map keeps its filters, selection and
 * zoom: nothing is reopened.
 */

import { api } from "../../lib/api.js";
import {
  SIN_CARPETA, TEXTOS, resolveSelection, selectionLabel, withFolder,
} from "../../lib/carpetas.js";
import { plural } from "../../lib/format.js";
import { getState, setState } from "../../lib/store.js";
import { toast, toastError } from "../ui/toast.js";
import { confirmDeleteFolder, moveToFolderDialog, promptFolderName } from "./FolderDialogs.js";

/** Fetch one dashboard's folders. Resolves with the list (the old one on error). */
export async function loadCarpetas(tipo) {
  try {
    const { carpetas } = await api.carpetas(tipo);
    setState((s) => ({
      carpetas: { ...s.carpetas, [tipo]: carpetas },
      carpetasError: { ...s.carpetasError, [tipo]: null },
      // A folder someone else deleted cannot stay selected.
      carpetaVista: { ...s.carpetaVista, [tipo]: resolveSelection(s.carpetaVista[tipo], carpetas) },
    }));
    return carpetas;
  } catch (error) {
    setState((s) => ({ carpetasError: { ...s.carpetasError, [tipo]: error.message } }));
    return getState().carpetas[tipo];
  }
}

export function selectFolder(tipo, seleccion) {
  setState((s) => ({ carpetaVista: { ...s.carpetaVista, [tipo]: seleccion } }));
}

export function createFolder(tipo) {
  promptFolderName({
    titulo: `Nueva carpeta de ${TEXTOS[tipo].plural}`,
    confirmar: "Crear carpeta",
    onSave: async (nombre) => {
      const { carpeta } = await api.createCarpeta(tipo, nombre);
      await loadCarpetas(tipo);
      selectFolder(tipo, carpeta.id);
      toast(`Carpeta «${carpeta.nombre}» creada.`);
      focusHeading(tipo);
    },
  });
}

export function renameFolder(tipo, carpeta) {
  if (!carpeta) return;
  promptFolderName({
    titulo: "Renombrar carpeta",
    nombre: carpeta.nombre,
    onSave: async (nombre) => {
      try {
        await api.renameCarpeta(carpeta.id, nombre);
      } catch (error) {
        if (error.status === 404) await loadCarpetas(tipo);
        throw error;
      }
      await loadCarpetas(tipo);
      toast("Carpeta renombrada.");
      focusHeading(tipo);
    },
  });
}

export async function deleteFolder(tipo, carpeta) {
  if (!carpeta) return;
  const conteo = getState()[tipo].filter((item) => item.carpeta_id === carpeta.id).length;
  if (!(await confirmDeleteFolder({ tipo, carpeta, conteo }))) return;

  try {
    const { trasladados } = await api.deleteCarpeta(carpeta.id);
    // Re-read the items rather than guess: another editor may have moved some.
    await reloadItems(tipo);
    await loadCarpetas(tipo);
    if (getState().carpetaVista[tipo] === carpeta.id) selectFolder(tipo, SIN_CARPETA);
    toast(
      `Se eliminó la carpeta «${carpeta.nombre}».` +
      (trasladados
        ? ` ${plural(trasladados, TEXTOS[tipo].singular, TEXTOS[tipo].plural)} ` +
          `${trasladados === 1 ? "pasó" : "pasaron"} a «Sin carpeta».`
        : "")
    );
    focusHeading(tipo);
  } catch (error) {
    toastError(error.message);
    if (error.status === 404) await loadCarpetas(tipo);
  }
}

/** Open the move dialog for one base (tipo "bases") or saved map ("mapas"). */
export function moveItem(tipo, item) {
  moveToFolderDialog({
    tipo,
    item,
    carpetas: getState().carpetas[tipo],
    reload: () => loadCarpetas(tipo),
    onMove: async (carpetaId) => {
      const respuesta = tipo === "bases"
        ? await api.moveBase(item.id, carpetaId)
        : await api.moveMapa(item.id, carpetaId);
      const actualizado = respuesta.base ?? respuesta.mapa;
      applyMembership(tipo, item.id, actualizado.carpeta_id);
      const desti

/* What the import assistant shows. Pure rendering: every handler comes in. */

import { estadoAutomatico, etiquetaFila } from "../../lib/asistente.js";
import { el } from "../../lib/dom.js";
import { fmtArea, fmtCount, fmtHectares, fmtPrice, fmtUnitPrice, plural } from "../../lib/format.js";
import { Conflicts, Findings, RejectedRows, Stat } from "./partes.js";

const ORIGENES = {
  usuario: "Tu elección", formato: "Formato guardado", nombre: "Nombre conocido", alias: "Sinónimo conocido",
  valores: "Por sus valores", ia: "Asistencia automática", predeterminado: "Sin reconocer", pendiente: "Pendiente",
};
const SEPARADORES = { ",": "Comas", ";": "Punto y coma", "\t": "Tabulaciones" };
const MONEDAS = { USD: "dólares estadounidenses (USD)", MXN: "pesos mexicanos (MXN)" };
const ORIGEN_MONEDA = {
  archivo: "lo indica el archivo", usuario: "según tu respuesta", formato: "del formato guardado",
};
/* Which currency the prices are in, and who said so. Never left implicit. */
const monedaTexto = (moneda, origen) =>
  `${MONEDAS[moneda] ?? moneda}${ORIGEN_MONEDA[origen] ? ` — ${ORIGEN_MONEDA[origen]}` : ""}`;
const idSeguro = (texto) => String(texto).replace(/[^a-zA-Z0-9_-]/g, "-");

export function Analizando() {
  return el("div", { class: "assistant-status", role: "status", "aria-live": "polite" },
    el("span", { class: "spinner", "aria-hidden": "true" }),
    el("div", {},
      el("p", { class: "assistant-status-title" }, "Analizando archivo…"),
      el("p", { class: "secondary" }, "Identificando la tabla, los encabezados, las columnas y cómo están escritos los números."),
    ),
  );
}

export function ErrorArchivo(mensaje) {
  return el("div", { class: "note note-aviso", role: "alert" }, mensaje);
}

export function Preguntas({ preguntas, respuestas, onChange }) {
  return el("section", { class: "assistant-questions", "aria-labelledby": "assistant-preguntas" },
    el("h3", { id: "assistant-preguntas", class: "eyebrow" },
      preguntas.length === 1 ? "Una pregunta antes de revisar" : `${preguntas.length} preguntas antes de revisar`),
    preguntas.map((p) =>
      el("fieldset", { class: "question" },
        el("legend", { class: "question-title" }, p.texto),
        p.detalle && el("p", { class: "secondary question-detail" }, p.detalle),
        p.opciones.map((o) => {
          const id = `q-${idSeguro(p.id)}-${o.indice}`;
