/* The history of one inventory terrain: who did what, when, and the values
 * before and after. Authenticated only; private values appear here because
 * every team member may read them. */

import { api } from "../../lib/api.js";
import { el } from "../../lib/dom.js";
import { fmtText } from "../../lib/format.js";
import { campo, mostrarValor, normalizarEvento } from "../../lib/inventario.js";
import { openDialog } from "../ui/dialog.js";

const fechaHora = new Intl.DateTimeFormat("es-MX", { dateStyle: "medium", timeStyle: "short" });
const cuando = (iso) => {
  const d = iso ? new Date(iso) : null;
  return d && !Number.isNaN(d.valueOf()) ? fechaHora.format(d) : "—";
};

export function openTerrainHistory({ id, nombre }) {
  const lista = el("ol", { class: "historial" });
  const estado = el("p", { class: "secondary", role: "status" }, "Cargando historial…");
  const mas = el("button", { type: "button", class: "btn btn-quiet", hidden: true }, "Cargar más");
  let cursor = null;

  async function cargar() {
    mas.disabled = true;
    estado.textContent = "Cargando historial…";
    estado.hidden = false;
    try {
      const pagina = await api.historial(id, cursor);
      const eventos = (pagina.eventos ?? pagina.events ?? pagina.historial ?? []).map(normalizarEvento);
      lista.append(...eventos.map(Evento));
      cursor = pagina.next_cursor ?? null;
      mas.hidden = cursor == null;
      estado.hidden = lista.childElementCount > 0;
      estado.textContent = "Todavía no hay cambios registrados.";
    } catch (error) {
      estado.hidden = false;
      estado.replaceChildren(
        `No se pudo cargar el historial: ${error.message} `,
        el("button", { type: "button", class: "link-btn", onclick: cargar }, "Reintentar"),
      );
    } finally {
      mas.disabled = false;
    }
  }
  mas.addEventListener("click", cargar);

  openDialog({
    titulo: "Historial",
    descripcion: nombre,
    ancho: "40rem",
    contenido: el("div", {}, estado, lista, mas),
    acciones: [{ etiqueta: "Cerrar", onClick: (close) => close() }],
  });
  cargar();
}

function Evento(evento) {
  return el("li", { class: "historial-evento" },
    el("p", { class: "historial-cabecera" },
      el("strong", {}, evento.accion),
      el("span", { class: "muted" }, ` · ${evento.actor} · ${cuando(evento.fecha)}`),
      evento.version != null && el("span", { class: "muted figure" }, ` · versión ${evento.version}`),
    ),
    evento.confirmados.length > 0 && el("p", { class: "secondary" },
      `Confirmó: ${evento.confirmados.join(" y ").toLowerCase()}.`),
    evento.cambios.length > 0 && el("ul", { class: "diff-list" },
      evento.cambios.map(({ campo: clave, antes, despues }) => {
        const c = campo(clave);
        const ver = (v) => (c ? mostrarValor(c, v) : fmtText(v));
        return el("li", { class: "diff" },
          el("span", { class: "diff-campo muted" }, c?.etiqueta ?? clave),
          el("span", { class: "diff-anterior" }, ver(antes)),
          el("span", { class: "diff-flecha", "aria-hidden": "true" }, "→"),
          el("span", { class: "diff-nuevo" }, ver(despues)),
        );
      })),
  );
}

/* Loading the catalog and the inventory: every page of the current query,
 * one query at a time.
 *
 * A newer query aborts the older one, so a late response can never replace
 * a newer result. Private loads are additionally cancelled by api.abortPrivate
 * when the session ends.
 */

import { api } from "../../lib/api.js";
import { consultaDe, reunirPaginas } from "../../lib/inventario.js";
import { getState, setDataset, setState } from "../../lib/store.js";

const ESPERA_MS = 250;   // typing settles before a query is sent
const controladores = {};
const esperas = {};
let detalleCtl = null;

const pedirPagina = {
  catalogo: api.publicoTerrenos,
  inventario: api.inventarioTerrenos,
};

/** Reload a dataset for its current filters, after a short pause by default. */
export function pedirCarga(tipo, { inmediato = false } = {}) {
  clearTimeout(esperas[tipo]);
  if (inmediato) return cargar(tipo);
  esperas[tipo] = setTimeout(() => cargar(tipo), ESPERA_MS);
  return undefined;
}

export async function cargar(tipo) {
  clearTimeout(esperas[tipo]);
  controladores[tipo]?.abort();
  const controlador = new AbortController();
  controladores[tipo] = controlador;
  const { signal } = controlador;

  const consulta = consultaDe(getState()[tipo].filtros, tipo);
  const clave = consulta.toString();
  setDataset(tipo, { cargando: true, error: null, progreso: { recibidos: 0, total: null } });

  try {
    const resultado = await reunirPaginas(
      (cursor) => pedirPagina[tipo](consulta, cursor, signal),
      {
        onProgreso: (recibidos, total) => {
          if (!signal.aborted) setDataset(tipo, { progreso: { recibidos, total } });
        },
      },
    );
    if (signal.aborted) return;
    setDataset(tipo, {
      registros: resultado.terrenos,
      facets: resultado.facets,
      consulta: clave,
      cargando: false,
      cargado: true,
      progreso: null,
    });
  } catch (error) {
    if (signal.aborted || error.name === "AbortError") return;
    // A failed refresh of the same query keeps what is on screen, labelled
    // stale; a failed new query must not leave the old query's rows standing
    // under the new filters.
    const misma = getState()[tipo].consulta === clave;
    setDataset(tipo, {
      cargando: false,
      progreso: null,
      error: error.message,
      ...(misma ? {} : { registros: [], facets: {}, consulta: null }),
    });
  }
}

/** Load the terrain behind `#/catalogo/:id` or `#/inventario/:id`. */
export async function cargarDetalle(tipo, id) {
  detalleCtl?.abort();
  detalleCtl = new AbortController();
  const { signal } = detalleCtl;
  setState({ detalle: { tipo, id, terreno: null, cargando: true, error: null } });
  try {
    const respuesta = tipo === "catalogo"
      ? await api.publicoTerreno(id, signal)
      : await api.inventarioTerreno(id, signal);
    if (signal.aborted) return;
    setState({ detalle: { tipo, id, terreno: respuesta?.terreno ?? respuesta, cargando: false, error: null } });
  } catch (error) {
    if (signal.aborted || error.name === "AbortError") return;
    const mensaje = error.status === 404
      ? (tipo === "catalogo"
        ? "Este terreno no está en el catálogo público."
        : "Este terreno no existe en el inventario.")
      : error.message;
    setState({ detalle: { tipo, id, terreno: null, cargando: false, error: mensaje } });
  }
}

/** Replace one inventory record in place after a save, without a reload. */
export function reemplazarRegistro(terreno) {
  const { inventario, detalle } = getState();
  setState({
    inventario: {
      ...inventario,
      registros: inventario.registros.map((t) => (t.id === terreno.id ? terreno : t)),
    },
    ...(detalle?.tipo === "inventario" && detalle.id === terreno.id
      ? { detalle: { ...detalle, terreno } } : {}),
  });
}

