        clave.value = "";
        clave.focus();
      } finally {
        entrar.disabled = false;
      }
    });

    const { dialog, close } = openDialog({
      titulo: "Iniciar sesión",
      descripcion: motivo ?? "Acceso para el equipo. Cada persona entra con su propio usuario.",
      ancho: "26rem",
