  }
  return request(`/importar/analizar${baseId ? `?base_id=${baseId}` : ""}`, {
    method: "POST", raw: true, body: file,
    headers: { "Content-Type": "application/octet-stream", "X-Archivo": encodeURIComponent(file.name) },
  });
}

