/* Base, application shell and the map workspace grid.
 *
 * Motion stays on transform/opacity; structure comes from hairline rules and
 * uneven spacing rather than uniform cards and shadows.
 *
 * The rest of the stylesheet lives beside this file:
 *   controls.css  buttons, inputs and the filter rail
 *   map.css       legend, basemap switcher, unplaced panel, Leaflet overrides
 *   panels.css    detail panel, table, screens, dialogs and toasts
 *   assistant.css the import assistant and format management
 */

/* Layout and components.
 * Motion is limited to transform/opacity; structure comes from hairline rules
 * and uneven spacing rather than uniform cards and shadows.
 */

*, *::before, *::after { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  background: var(--paper);
  overflow: hidden;
}

button, input, select, textarea { font: inherit; color: inherit; }

:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

.skip-link {
  position: absolute;
  top: var(--space-2);
  left: var(--space-2);
  z-index: var(--z-toast);
  padding: var(--space-2) var(--space-3);
  background: var(--ink);
  color: var(--ink-inverse);
  border-radius: var(--radius);
  transform: translateY(-200%);
  transition: transform var(--duration-fast) var(--ease-out-expo);
}
.skip-link:focus { transform: translateY(0); }

/* ------------------------------------------------------------------ shell */

.app {
  display: grid;
  grid-template-rows: var(--header-height) 1fr;
  /* Without minmax(0, ...) the column grows to the header's min-content
   * width, and on a phone the whole app was laid out wider than the screen. */
  grid-template-columns: minmax(0, 1fr);
  height: 100vh;
  height: 100dvh;
}

.app-header {
  display: flex;
  align-items: center;
  gap: var(--space-6);
  padding-inline: var(--space-5);
  background: var(--paper-raised);
  border-bottom: 1px solid var(--rule);
}

.brand { display: flex; align-items: center; gap: var(--space-2); min-width: 0; }
.brand-name,
.brand .chip,
.nav-item { white-space: nowrap; }

/* The supplied logo, at its own 522:478 proportion. object-fit guards the
 * shape if the box is ever constrained differently. */
.brand-logo {
  display: block;
  height: 32px;
  width: auto;
  max-width: 35px;      /* 32 x 522 / 478, rounded */
  object-fit: contain;
  flex-shrink: 0;
}

.brand-name {
  font-weight: 600;
  letter-spacing: var(--tracking-tight);
  font-size: var(--text-lead);
}

.nav { display: flex; gap: var(--space-1); }

.nav-item {
  padding: var(--space-2) var(--space-3);
  background: none;
  border: none;
  border-radius: var(--radius);
  color: var(--ink-secondary);
  cursor: pointer;
  transition: background var(--duration-fast), color var(--duration-fast);
}
.nav-item:hover { background: var(--paper-sunken); color: var(--ink); }
.nav-item.is-active { background: var(--ink); color: var(--ink-inverse); }

.app-main { overflow: hidden; min-height: 0; }

/* -------------------------------------------------------------- workspace */

.workspace {
  display: grid;
  grid-template-columns: var(--rail-width) minmax(0, 1fr);
  height: 100%;
  min-height: 0;
}
.workspace:has(.detail-slot) {
  grid-template-columns: var(--rail-width) minmax(0, 1fr) var(--panel-width);
}

.rail-slot {
  overflow-y: auto;
  border-right: 1px solid var(--rule);
  background: var(--paper-raised);
}

.stage-slot {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  /* Without an explicit minmax(0, ...) the column takes the toolbar's
   * min-content width, which pushed the map past this column and painted it
   * over the detail panel on narrower screens. */
  grid-template-columns: minmax(0, 1fr);
  min-width: 0;
  min-height: 0;
}

.detail-slot {
  overflow-y: auto;
  background: var(--paper-overlay);
  border-left: 1px solid var(--rule);
  box-shadow: var(--shadow-panel);
  animation: panel-in var(--duration-normal) var(--ease-out-e

/* Inventory, catalog and session surfaces.
 *
 * Same instrument as the rest: hairlines, ink, warm paper. Colour appears only
 * where it carries meaning (publication status, warnings), and always beside a
 * word that says the same thing.
 */

/* ---------------------------------------------------------------- session */

a.nav-item { text-decoration: none; display: inline-flex; align-items: center; }

.session {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  margin-left: auto;
  min-width: 0;
}
.session-user {
  max-width: 14rem;
  font-size: var(--text-small);
  color: var(--ink-secondary);
}

.login-form .btn { width: 100%; justify-content: center; margin-top: var(--space-2); }
.login-form .rail-field { margin-bottom: var(--space-4); }

/* ----------------------------------------------------------- status chips */

.estado-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2);
  margin-top: var(--space-2);
}
.estado-fecha { margin-top: var(--space-1); font-size: var(--text-micro); }

.estado-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4em;
  padding: 1px var(--space-2);
  border: 1px solid var(--rule-strong);
  border-radius: 999px;
  font-size: var(--text-micro);
  font-weight: 600;
  white-space: nowrap;
  color: var(--ink);
}
.estado-chip::before {
  content: "";
  width: 0.55em;
  height: 0.55em;
  border-radius: 50%;
  border: 1.5px solid currentColor;
}
.estado-publicado::before { background: var(--status-ok); border-color: var(--status-ok); }
.estado-pendiente::before { background: var(--status-aviso); border-color: var(--status-aviso); }
.estado-fuera::before,
.disp-sold::before,
.disp-withdrawn::before { background: var(--status-error); border-color: var(--status-error); }
.estado-archivado { color: var(--ink-muted); }
.disp-available::before { background: var(--status-ok); border-color: var(--status-ok); }
.disp-negotiation::before { background: var(--status-aviso); border-color: var(--status-aviso); }
.disp-unknown { color: var(--ink-secondary); }

/* ---------------------------------------------------------------- detail */

.detail-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  padding: var(--space-3) 0;
}
.detail-descripcion {
