  white-space: pre-line;
  border-bottom: 1px solid var(--rule);
}

/* The private block reads as a different, inward-facing surface. */
.privado {
  margin-top: var(--space-5);
  padding: var(--space-3) var(--space-4) 0;
  background: var(--paper-sunken);
  border-radius: var(--radius-lg);
}
.privado .detail-section:last-child { border-bottom: none; }
.privado-titulo { padding-bottom: var(--space-1); }
.pre { white-space: pre-line; }

/* ----------------------------------------------------------------- editor */

.editor { max-width: 62rem; padding-bottom: 0; }
.editor .screen-header { margin-bottom: var(--space-4); }
.editor .screen-header h1 { font-size: var(--text-title); }

.editor-form { display: flex; flex-direction: column; gap: var(--space-5); }

.editor-seccion {
  margin: 0;
  padding: var(--space-4) 0 0;
  border: none;
  border-top: 1px solid var(--rule-strong);
}
.editor-seccion > legend { padding: 0 var(--space-2) 0 0; }
.editor-privado {
  padding: var(--space-4);
  background: var(--paper-sunken);
  border-top: none;
  border-radius: var(--radius-lg);
}
.editor-privado > legend { float: left; width: 100%; margin-bottom: var(--space-3); }
.editor-privado > legend + * { clear: both; }

.editor-instruccion { max-width: 60ch; margin: var(--space-2) 0 var(--space-3); font-size: var(--text-small); }

.editor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(14rem, 1fr));
  gap: var(--space-4) var(--space-5);
  margin-top: var(--space-3);
}
.editor-field { min-width: 0; }
.editor-field-ancho { grid-column: 1 / -1; }
.editor-field textarea { resize: vertical; min-height: 4.5rem; }

/* Everything that floats over the map, plus Leaflet's own chrome. */

/* ----------------------------------------------------------------- legend */

.legend {
  min-width: 13rem;
  max-width: 17rem;
  padding: var(--space-3);
  background: oklch(100% 0 0 / 0.94);
  backdrop-filter: blur(8px);
  border: 1px solid var(--rule);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-pop);
}

.legend-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--space-3);
  padding-bottom: var(--space-2);
  margin-bottom: var(--space-2);
  border-bottom: 1px solid var(--rule);
}
.legend-count { font-size: var(--text-micro); color: var(--ink-secondary); }

.legend-list { list-style: none; margin: 0; padding: 0; }
.legend-item {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: 2px 0;
  font-size: var(--text-small);
  cursor: pointer;
  min-width: 0;
}
.legend-item input { accent-color: var(--ink); margin: 0; flex-shrink: 0; }
.legend-item.is-off .legend-label,
.legend-item.is-off .legend-swatch { opacity: 0.35; }
.legend-label { flex: 1; min-width: 0; }

.legend-swatch {
  width: 11px; height: 11px;
  border-radius: 3px;
  border: 1px solid oklch(19% 0.006 60 / 0.15);
  flex-shrink: 0;
}

.legend-note {
  margin-top: var(--space-2);
  padding-top: var(--space-2);
  border-top: 1px solid var(--rule);
  font-size: var(--text-micro);
  color: var(--ink-muted);
