}

.legend-ramp { display: flex; flex-direction: column; gap: 2px; }
.ramp-step { display: flex; align-items: center; gap: var(--space-2); font-size: var(--text-micro); }
.ramp-swatch { width: 18px; height: 11px; border-radius: 2px; flex-shrink: 0; }
.ramp-label { color: var(--ink-secondary); }
.ramp-step-unknown { margin-top: 3px; }

/* ------------------------------------------------------- basemap switcher */

.basemap-switcher {
  display: inline-flex;
  padding: 3px;
  background: oklch(100% 0 0 / 0.94);
  backdrop-filter: blur(8px);
  border: 1px solid var(--rule);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-pop);
}
.basemap-option {
  padding: var(--space-1) var(--space-3);
  background: none;
  border: none;
  border-radius: var(--radius-sm);
  font-size: var(--text-micro);
  font-weight: 500;
  color: var(--ink-secondary);
  cursor: pointer;
  transition: background var(--duration-fast), color var(--duration-fast);
}
.basemap-option:hover { background: var(--paper-sunken); color: var(--ink); }
