/* --------------------------------------------------------------- unplaced */

.unplaced {
  position: absolute;
  right: var(--space-4);
  /* clears Leaflet's attribution strip along the bottom edge */
  bottom: calc(var(--space-4) + 14px);
  z-index: var(--z-overlay);
  /* Collapsed it is just a button, so it only claims the width it needs and
   * stops crowding the legend on a narrow stage. */
  width: auto;
  max-width: calc(100% - var(--space-6));
  max-height: calc(100% - var(--space-7));
  display: flex;
  flex-direction: column;
  background: oklch(100% 0 0 / 0.96);
  backdrop-filter: blur(8px);
  border: 1px solid var(--rule);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-pop);
  overflow: hidden;
}
