  container-type: inline-size;
}

.detail-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-3);
  padding-bottom: var(--space-4);
  border-bottom: 1px solid var(--rule);
}
.detail-heading { min-width: 0; }
.detail-heading h2 { margin: var(--space-1) 0; }

.detail-lead {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  padding: var(--space-4) 0;
  border-bottom: 1px solid var(--rule);
}
.detail-lead .figure-lead {
  /* A nine-figure peso amount has to fit a narrow panel without clipping. */
  font-size: clamp(1.5rem, 7.5cqi, 2.125rem);
  overflow-wrap: anywhere;
}
.detail-lead-sub { display: flex; align-items: baseline; gap: var(--space-3); }
.figure-sub {
  font-size: var(--text-lead);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  letter-spacing: var(--tracking-tight);
}

.detail-section { padding: var(--space-4) 0; border-bottom: 1px solid var(--rule); }
.detail-section h3 { margin-bottom: var(--space-2); }

.detail-grid {
  display: grid;
  grid-template-columns: minmax(6.5rem, auto) minmax(0, 1fr);
  gap: var(--space-2) var(--space-4);
  margin: 0;
  font-size: var(--text-small);
}
.detail-grid dt { color: var(--ink-muted); }
.detail-grid dd { margin: 0; overflow-wrap: anywhere; }

.detail-unplaced .btn { margin-top: var(--space-3); }
.detail-unplaced p { font-size: var(--text-small); line-height: 1.5; }

.detail-footer { padding-top: var(--space-4); font-size: var(--text-micro); }

.detail-empty { display: grid; place-items: center; }

/* --------------------------------------------------------------- findings */

.findings { padding: var(--space-3) 0; display: flex; flex-direction: column; gap: var(--space-2); }

.finding {
  display: flex;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius);
  border-left: 3px solid;
  font-size: var(--text-small);
  line-height: 1.45;
}
.finding-error {
  border-left-color: var(--status-error);
  background: oklch(from var(--status-error) 96% 0.02 h);
}
.finding-aviso {
  border-left-color: var(--status-aviso);
  background: oklch(from var(--status-aviso) 96% 0.02 h);
}

/* The icon + label pairing: severity never rides on colour alone. */
.finding-icon {
  display: grid;
  place-items: center;
  width: 16px; height: 16px;
  flex-shrink: 0;
  margin-top: 1px;
  border-radius: 50%;
  font-size: 0.65rem;
  font-weight: 700;
  color: var(--ink-inverse);
}
.finding-error .finding-icon { background: var(--status-error); }
.finding-aviso .finding-icon { background: var(--status-aviso); }

/* ------------------------------------------------------------------ table */

.table-panel {
  position: absolute;
  inset: 0;
  /* Above the map and its Leaflet controls, which sit in the 400-1000 band. */
  z-index: var(--z-panel);
  background: var(--paper-raised);
  overflow: auto;
}

.table-wrap { min-width: 0; }

.table { width: 100%; border-collapse: collapse; font-size: var(--text-small); }

.table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  padding: var(--space-2) var(--space-3);
  background: var(--paper-raised);
  border-bottom: 1px solid var(--rule-strong);
  text-align: left;
  font-size: var(--text-micro);
  font-weight: 600;
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  color: var(--ink-muted);
  white-space: nowrap;
}
.table th.is-num, .table td.is-num { text-align: right; }
.table th.is-active { color: var(--ink); }

.th-btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  background: none;
  border: none;
  padding: 0;
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.th-btn:hover { color: var(--ink); }
.sort-caret { font-size: 0.6rem; }

